import React, { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import "./clippreview.css";

function ClipPreview() {
    const location = useLocation();
    const { clipPaths = [], videoURL = null } = location.state || {}; // Default values for safety
    const [error, setError] = useState(null);

    useEffect(() => {
        // Debugging: Log the received payload
        console.log("Received clipPaths:", clipPaths);

        // Check if clipPaths is valid
        if (!clipPaths || clipPaths.length === 0) {
            setError("No clips found to display.");
        } else if (!Array.isArray(clipPaths)) {
            setError("Invalid clip paths format.");
        }
    }, [clipPaths]);

    return (
        <div className="clipping-app">
            <header className="header">
                <h1 className="logo">
                    <span className="bold">Channel-</span>
                    <span className="highlight">IQ</span>
                </h1>
                <nav className="nav">
                    <a href="#clipper">Clipper</a>
                    <a href="#seo">SEO</a>
                    <a href="#thumbnail">Thumbnail</a>
                    <a href="#pricing">Pricing</a>
                    <button className="sign-in">Sign in</button>
                    <button className="sign-up">Sign up</button>
                </nav>
            </header>

            <main className="main-content">
                <section className="clipper-section">
                    <button className="clipper-btn">Clipper</button>

                    {/* Display Long Video */}
                    <div className="long-video">
                        <h2>Your Long Video</h2>
                        <div className="video-preview">
                            {videoURL ? (
                                <video src={videoURL} controls className="preview-video" />
                            ) : (
                                <p>No video URL provided.</p>
                            )}
                        </div>
                    </div>

                    {/* Display Extracted Clips */}
                    <div className="viral-clips">
                        <h3>Your Viral Clips</h3>
                        <div className="clip-thumbnails">
                            {error ? (
                                <p className="error-message">{error}</p>
                            ) : (
                                clipPaths.map((clipPath, index) => (
                                    <div key={index} className="clip-container">
                                        <video
                                            src={clipPath}
                                            controls
                                            className="clip-thumbnail"
                                        />
                                        <p className="clip-label">Clip {index + 1}</p>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
                </section>
            </main>
        </div>
    );
}

export default ClipPreview;
